def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # Same-color diagonal pairs mark a diagonal to be extended across the board.
    pairs = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color:
                    pairs.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in pairs:
        rr, cc = r, c
        while 0 <= rr - dr < h and 0 <= cc - dc < w:
            rr -= dr; cc -= dc
        while 0 <= rr < h and 0 <= cc < w:
            if out[rr][cc] == bg:
                out[rr][cc] = color
            rr += dr; cc += dc
    return out
